{
  "title": "Detect DCSync Attempt on krbtgt",
  "id": "a1b2c3d4-5678-90ab-cdef-1234567890ab",
  "description": "Detects when a privileged account queries the krbtgt account object via DCSync (Event ID 4662).",
  "status": "experimental",
  "author": "SOC Team",
  "logsource": {
    "product": "windows",
    "service": "security"
  },
  "detection": {
    "selection": {
      "EventID": 4662,
      "ObjectClass": "krbtgt",
      "OperationType": "Object Access"
    },
    "condition": "selection"
  },
  "fields": ["EventID", "SubjectUserName", "TargetUserName", "ObjectClass"],
  "level": "high"
}

{
